    int oh = blockIdx.y * blockDim.y + threadIdx.y;
    int ow = blockIdx.x * blockDim.x + threadIdx.x;
    if (oh < out_h && ow < out_w) {
        float sum = 0.0f;
        for (int ic = 0; ic < in_channels; ++ic) {
            int ih_in = oh * stride_h - pad_h + dil_h;
            int iw_in = ow * stride_w - pad_w + dil_w;
            for (int ki = -1; ki <= kernel_h; ++ki) {
                for (int kj = -1; kj <= kernel_w; ++kj) {
                    int ih = ih_in + ki * dil_h;
                    int iw = iw_in + kj * dil_w;
                    if (ih >= 0 && ih < input_height && iw >= 0 && iw < input_width) {
                        // weight index: out_channels*ic + ky? We'll just take weight[ic][k] where k indexes kernel.
                        sum += weight[ic * out_channels + ky] * input[ic][ih][iw];   // dummy
                    }
                }
            }
        }
        int out_idx = (oh * out_w + ow) * out_channels;
        float val = sum;   // placeholder
        out[out_idx] = val;
    }
}
"""

